// Get the input data from the previous node (the If node)
const inputData = $json;

// Define the name-to-Slack ID mapping
const slackIdMap = {
  'TeamMember': '<@YOUR_SLACK_USER_ID>'
};

// Extract the required information
const meetingTitle = inputData.response.data.output.meeting_title;
const summary = inputData.response.data.output.meeting_summary;
const actionPointsArray = inputData.response.data.output.action_points;

// Format Action Points with Slack IDs
let formattedActionPoints = '';
if (actionPointsArray && actionPointsArray.length > 0) {
  actionPointsArray.forEach((item, index) => {
    formattedActionPoints += `*${index + 1}.* ${item.task_description}\n`;
    if (item.assigned_to) {
      // Split names by ' and ' to handle multiple assignees
      const assignedNames = item.assigned_to.split(' and ');
      const mappedIds = assignedNames.map(name => {
        const trimmedName = name.trim();
        return slackIdMap[trimmedName] || trimmedName; // Fallback to name if not in map
      });
      formattedActionPoints += `   :bust_in_silhouette: *Assigned To:* ${mappedIds.join(' and ')}\n`;
    }
    if (item.due_date) {
      formattedActionPoints += `   :calendar: *Due Date:* ${item.due_date}\n`;
    }
    formattedActionPoints += '\n'; // Add an extra newline for spacing
  });
}

// Construct the final formatted message
const formattedMessage = `
:wave: *New Meeting Summary*\n
*Meeting Title:* ${meetingTitle}\n
_Summary:_
${summary}\n
_Action Points:_
${formattedActionPoints}`;

// Return the result with the new formatted message
return [{
  json: {
    slackMessage: formattedMessage
  }
}];

// Get webhook data and transcript data
const meetingData = $('VideoDB Get Meeting').first().json.data;
const transcriptData = $('VideoDB Transcript').first().json.data;

/**
 * Groups consecutive words by the same speaker into segments.
 * Handles silence markers and creates coherent conversation segments.
 */
function groupWordsIntoSegments(wordData) {
    if (!wordData || wordData.length === 0) {
        return [];
    }

    const segments = [];
    let currentSegment = null;

    for (const word of wordData) {
        // Skip silence markers and entries without speaker info
        if (!word.speaker || word.speaker === "-" || !word.text || word.text === "-") {
            continue;
        }

        // Start new segment if speaker changes or this is the first word
        if (!currentSegment || currentSegment.speakerLabel !== word.speaker) {
            // Save previous segment if exists
            if (currentSegment) {
                segments.push({
                    speakerLabel: currentSegment.speakerLabel,
                    start: currentSegment.start,
                    end: currentSegment.end,
                    text: currentSegment.words.join(" ").trim()
                });
            }

            // Start new segment
            currentSegment = {
                speakerLabel: word.speaker,
                start: word.start,
                end: word.end,
                words: [word.text]
            };
        } else {
            // Continue current segment
            currentSegment.words.push(word.text);
            currentSegment.end = word.end;
        }
    }

    // Don't forget the last segment
    if (currentSegment) {
        segments.push({
            speakerLabel: currentSegment.speakerLabel,
            start: currentSegment.start,
            end: currentSegment.end,
            text: currentSegment.words.join(" ").trim()
        });
    }

    return segments;
}

/**
 * Creates a mapping from speaker labels (A, B, etc.) to actual names
 * using a scoring system based on temporal proximity and pattern matching.
 */
function createSpeakerMapping(segments, speakerTimeline) {
    // Get unique speaker labels from transcript
    const uniqueLabels = [...new Set(segments.map(s => s.speakerLabel))];

    // Get unique speaker names from timeline (excluding Unknown)
    const uniqueNames = [...new Set(
        speakerTimeline
            .filter(entry => entry.speaker_name && entry.speaker_name !== "Unknown Speaker")
            .map(entry => entry.speaker_name)
    )];

    // If we have a simple 1-to-1 or 2-to-2 mapping, use advanced scoring
    if (uniqueLabels.length <= uniqueNames.length && uniqueNames.length <= 3) {
        return createAdvancedMapping(segments, speakerTimeline, uniqueLabels, uniqueNames);
    }

    // Fallback to simple proximity-based mapping
    return createProximityMapping(segments, speakerTimeline, uniqueLabels);
}

/**
 * Advanced mapping using scoring based on multiple factors
 */
function createAdvancedMapping(segments, timeline, labels, names) {
    const mapping = {};
    const scores = {};

    // Initialize scores
    for (const label of labels) {
        scores[label] = {};
        for (const name of names) {
            scores[label][name] = 0;
        }
    }

    // Score based on temporal proximity
    for (const segment of segments) {
        const segmentMidpoint = (segment.start + segment.end) / 2;

        for (const entry of timeline) {
            if (entry.speaker_name === "Unknown Speaker") continue;

            const timeDiff = Math.abs(segmentMidpoint - entry.start_time_seconds);

            // Score inversely proportional to time difference
            // Closer events get higher scores
            const proximityScore = Math.max(0, 10 - timeDiff);

            // Bonus points for exact or very close matches
            if (timeDiff < 0.5) {
                scores[segment.speakerLabel][entry.speaker_name] += 20;
            } else if (timeDiff < 2) {
                scores[segment.speakerLabel][entry.speaker_name] += 10;
            }

            scores[segment.speakerLabel][entry.speaker_name] += proximityScore;
        }
    }

    // Analyze conversation patterns
    // If speakers alternate frequently, boost scores for alternating pattern
    if (segments.length > 4) {
        const alternationBonus = analyzeAlternationPattern(segments, timeline, names);
        for (const label in alternationBonus) {
            for (const name in alternationBonus[label]) {
                scores[label][name] += alternationBonus[label][name];
            }
        }
    }

    // Assign each label to the name with highest score
    const usedNames = new Set();

    // Sort labels by their max score to assign high-confidence mappings first
    const sortedLabels = labels.sort((a, b) => {
        const maxA = Math.max(...Object.values(scores[a]));
        const maxB = Math.max(...Object.values(scores[b]));
        return maxB - maxA;
    });

    for (const label of sortedLabels) {
        let bestName = null;
        let bestScore = -1;

        for (const name of names) {
            if (!usedNames.has(name) && scores[label][name] > bestScore) {
                bestScore = scores[label][name];
                bestName = name;
            }
        }

        if (bestName) {
            mapping[label] = bestName;
            usedNames.add(bestName);
        }
    }

    // Fallback for any unmapped labels
    for (const label of labels) {
        if (!mapping[label]) {
            // Assign to any unused name or first available name
            const unusedName = names.find(n => !usedNames.has(n));
            mapping[label] = unusedName || names[0];
        }
    }

    return mapping;
}

/**
 * Analyzes conversation alternation patterns to improve speaker identification
 */
function analyzeAlternationPattern(segments, timeline, names) {
    const bonus = {};
    const labels = [...new Set(segments.map(s => s.speakerLabel))];

    // Initialize bonus structure
    for (const label of labels) {
        bonus[label] = {};
        for (const name of names) {
            bonus[label][name] = 0;
        }
    }

    // Look for alternating speaker patterns in timeline
    for (let i = 0; i < timeline.length - 1; i++) {
        const current = timeline[i];
        const next = timeline[i + 1];

        if (current.speaker_name === "Unknown Speaker" || 
            next.speaker_name === "Unknown Speaker") continue;

        // Find segments that match this alternation timing
        for (let j = 0; j < segments.length - 1; j++) {
            const seg1 = segments[j];
            const seg2 = segments[j + 1];

            // Check if segment timing aligns with timeline alternation
            const timeDiff1 = Math.abs(seg1.start - current.start_time_seconds);
            const timeDiff2 = Math.abs(seg2.start - next.start_time_seconds);

            if (timeDiff1 < 3 && timeDiff2 < 3 && seg1.speakerLabel !== seg2.speakerLabel) {
                bonus[seg1.speakerLabel][current.speaker_name] += 5;
                bonus[seg2.speakerLabel][next.speaker_name] += 5;
            }
        }
    }

    return bonus;
}

/**
 * Simple proximity-based mapping for complex scenarios
 */
function createProximityMapping(segments, timeline, labels) {
    const mapping = {};

    for (const label of labels) {
        const labelSegments = segments.filter(s => s.speakerLabel === label);
        if (labelSegments.length === 0) continue;

        // Find the most common speaker name near this label's segments
        const nameCounts = {};

        for (const segment of labelSegments) {
            const nearestSpeaker = findNearestSpeaker(segment.start, timeline);
            if (nearestSpeaker && nearestSpeaker !== "Unknown Speaker") {
                nameCounts[nearestSpeaker] = (nameCounts[nearestSpeaker] || 0) + 1;
            }
        }

        // Assign the most frequent nearby speaker
        let bestName = null;
        let bestCount = 0;
        for (const [name, count] of Object.entries(nameCounts)) {
            if (count > bestCount) {
                bestCount = count;
                bestName = name;
            }
        }

        mapping[label] = bestName || "Unknown Speaker";
    }

    return mapping;
}

/**
 * Finds the nearest speaker at or before the given timestamp
 */
function findNearestSpeaker(timestamp, timeline) {
    let nearestSpeaker = null;
    let nearestTime = -Infinity;

    for (const entry of timeline) {
        if (entry.start_time_seconds <= timestamp && 
            entry.start_time_seconds > nearestTime) {
            nearestTime = entry.start_time_seconds;
            nearestSpeaker = entry.speaker_name;
        }
    }

    // If no speaker found before timestamp, look for closest after
    if (!nearestSpeaker) {
        let minDiff = Infinity;
        for (const entry of timeline) {
            const diff = Math.abs(entry.start_time_seconds - timestamp);
            if (diff < minDiff) {
                minDiff = diff;
                nearestSpeaker = entry.speaker_name;
            }
        }
    }

    return nearestSpeaker;
}

/**
 * Applies the speaker mapping to segments and handles edge cases
 */
function assignSpeakers(segments, speakerMapping) {
    const finalTranscript = [];
    let lastKnownSpeaker = null;

    for (const segment of segments) {
        let assignedSpeaker = speakerMapping[segment.speakerLabel];

        // Handle unknown speakers
        if (!assignedSpeaker || assignedSpeaker === "Unknown Speaker") {
            // Try to use last known speaker if the gap is small
            if (lastKnownSpeaker && segments.indexOf(segment) > 0) {
                const prevSegment = segments[segments.indexOf(segment) - 1];
                const gap = segment.start - prevSegment.end;

                // If gap is less than 2 seconds, likely the same speaker
                if (gap < 2) {
                    assignedSpeaker = lastKnownSpeaker;
                }
            }
        }

        // Update last known speaker if we have a valid assignment
        if (assignedSpeaker && assignedSpeaker !== "Unknown Speaker") {
            lastKnownSpeaker = assignedSpeaker;
        }

        finalTranscript.push({
            speaker: assignedSpeaker || "Unknown Speaker",
            text: segment.text
        });
    }

    return finalTranscript;
}

/**
 * Post-processing to merge consecutive segments from the same speaker
 */
function mergeConsecutiveSegments(transcript) {
    if (transcript.length === 0) return transcript;

    const merged = [];
    let currentMerged = { ...transcript[0] };

    for (let i = 1; i < transcript.length; i++) {
        const segment = transcript[i];

        // Check if same speaker and small time gap
        if (segment.speaker === currentMerged.speaker && 
            segment.start - currentMerged.end < 1.0) {
            // Merge segments
            currentMerged.end = segment.end;
            currentMerged.text += " " + segment.text;
        } else {
            // Save current and start new
            merged.push(currentMerged);
            currentMerged = { ...segment };
        }
    }

    // Don't forget the last segment
    merged.push(currentMerged);

    return merged;
}

// Main processing pipeline
try {
    // Extract the required data
    const speakerTimeline = meetingData.speaker_timeline;
    const wordData = transcriptData.word_timestamps;

    // Step 1: Group words into conversation segments
    const segments = groupWordsIntoSegments(wordData);

    // Step 2: Create speaker label to name mapping
    const speakerMapping = createSpeakerMapping(segments, speakerTimeline);

    // Step 3: Apply mapping to segments
    const transcript = assignSpeakers(segments, speakerMapping);

    // Step 4: Merge consecutive segments from same speaker
    const finalTranscript = mergeConsecutiveSegments(transcript);

    // Get the current date and time
    const now = new Date();
    const formattedDate = now.getFullYear() + '-' +
        ('0' + (now.getMonth() + 1)).slice(-2) + '-' +
        ('0' + now.getDate()).slice(-2);

    // Return the result
    return [{
        date: formattedDate,
        transcript: finalTranscript
    }];
} catch (error) {
    return [{
        error: error.message,
        date: new Date().toISOString(),
        transcript: []
    }];
}

const inputData = $json.response.data.output.action_points;
let formattedActionPoints = '';

if (inputData && inputData.length > 0) {
  inputData.forEach((item, index) => {
    formattedActionPoints += `${index + 1}. Task: ${item.task_description}\n`;
    if (item.assigned_to) {
      formattedActionPoints += `   Assigned To: ${item.assigned_to}\n`;
    }
    if (item.due_date) {
      formattedActionPoints += `   Due Date: ${item.due_date}\n`;
    }
  });
}

return [
  {
    json: {
      ...$json,
      response: {
        ...$json.response,
        data: {
          ...$json.response.data,
          output: {
            ...$json.response.data.output,
            action_points: formattedActionPoints
          }
        }
      }
    }
  }
];
